// ============================================================
// PRE-FILTER: Only pass emails from allowed partner domains
// or pure forwards from person2@company.com / person2@company.com
// Zero cost — no GPT, no HubSpot calls.
// ============================================================

const ALLOWED_DOMAINS = [
  'partner1.com',
  'partner2.com',
  'partner3.com',
  'partner4.com',
  'partner5.com',
  'partner6.com',
  'partner7.com'
];

const ALI_EMAILS = ['person2@company.com', 'person2@company.com'];

const email = $input.first().json;
const fromAddress = (email.from?.emailAddress?.address || '').toLowerCase().trim();
const senderDomain = fromAddress.split('@')[1] || '';

// Direct partner email
const isFromPartner = ALLOWED_DOMAINS.some(d => senderDomain === d);

// Ali forwarding a partner intro
const isAliForward = ALI_EMAILS.includes(fromAddress);

if (!isFromPartner && !isAliForward) {
  // Stop silently — not from a relevant sender
  return [];
}

// For Ali forwards: body must contain a quoted email from a partner domain
if (isAliForward) {
  const body = (email.body?.content || '').toLowerCase();
  const hasPartnerContent = ALLOWED_DOMAINS.some(d => body.includes(`@${d}`));
  if (!hasPartnerContent) {
    return [];
  }
}

// Pass through with sender metadata attached
return [{
  json: {
    ...email,
    _senderDomain: senderDomain,
    _isAliForward: isAliForward,
    _fromAddress: fromAddress
  }
}];

