now.setUTCHours(0, 0, 0, 0);
const introDateTimestamp = now.getTime();
const closeDate = new Date(now);
closeDate.setDate(closeDate.getDate() + 14);
const closeDateTimestamp = closeDate.getTime();

return [{
  json: {
    // GPT extracted fields
    company_name: gpt.company_name,
    lead_contacts: gpt.lead_contacts || [],
    introducer_name: gpt.introducer_name || null,
    source: gpt.source,
    lead_domain: gpt.lead_domain,
    employees: gpt.employees || null,
    infrastructure: gpt.infrastructure || null,
    deliverables: gpt.deliverables || null,
    gpt_reason: gpt.reason,
    // Email metadata
    subject: email.subject,
    receivedDateTime: email.receivedDateTime,
    webLink: email.webLink || null,
    emailBody: email.body?.content || '',
    fromAddress: email.from?.emailAddress?.address || '',
    fromName: email.from?.emailAddress?.name || '',
    // Timestamps
    introDate: introDateTimestamp,
    closeDate: closeDateTimestamp,
    // Validation
    isValid: issues.length === 0,
    validationIssues: issues
  }
}];

