// Expand lead_contacts array into individual items for HubSpot contact creation
// Filters out any yourcompany.com or partner domain emails that GPT may have included

const EXCLUDE_DOMAINS = [
  'yourcompany.com',
  'partner1.com',
  'partner2.com',
  'partner3.com',
  'partner4.com',
  'partner5.com',
  'partner6.com',
  'partner7.com'
];

const data = $input.first().json;
const contacts = data.lead_contacts || [];

const filtered = contacts.filter(c => {
  const domain = (c.email || '').split('@')[1] || '';
  return !EXCLUDE_DOMAINS.includes(domain);
});

if (filtered.length === 0) return [];

return filtered.map(c => {
  const parts = (c.name || '').trim().split(' ');
  const firstName = parts[0] || '';
  const lastName = parts.slice(1).join(' ') || '';
  return {
    json: {
      email: c.email,
      firstname: firstName,
      lastname: lastName,
      // Pass through parent data for downstream nodes
      _parentData: data
    }
  };
});

// Merge: collect all contact vids + company data + extracted info
// Runs after both Update company branch and direct branch converge

const vids = $('Create or update a contact').all()
  .map(item => item.json.vid)
  .filter(Boolean);

const extracted = $('Code: Validate + Prepare data').first().json;

// Company from search — try both branches
let companyData;
try {
  companyData = $('Update a company').first().json;
} catch(e) {
  companyData = $('Search for a company by Domain').first().json;
}

const companyNameFromHS = companyData?.properties?.name?.value || null;

return [{
  json: {
    allVids: vids,
    companyId: companyData?.companyId || null,
    dealName: companyNameFromHS || extracted.company_name,
    company_name: extracted.company_name,
    lead_domain: extracted.lead_domain,
    source: extracted.source,
    introducer_name: extracted.introducer_name,
    introDate: extracted.introDate,
    closeDate: extracted.closeDate,
    subject: extracted.subject,
    emailBody: extracted.emailBody,
    fromAddress: extracted.fromAddress,
    fromName: extracted.fromName,
    lead_contacts: extracted.lead_contacts,
    employees: extracted.employees,
    infrastructure: extracted.infrastructure,
    deliverables: extracted.deliverables
  }
}];

