// Convert GPT reply text to HTML for Outlook
// Also build To/CC recipient lists and Graph API reply body

const gptContent = $('GPT: Draft reply email').first().json.message.content;
const extracted = $('Code: Merge contact IDs').first().json;
const emailRaw = $('Get a message').first().json;

// Convert Slack-style links and newlines to HTML
const htmlContent = gptContent
  .replace(/<(https?:\/\/[^|>]+)\|([^>]+)>/g, '<a href="$1">$2</a>')
  .replace(/\n/g, '<br>');

// Lead contacts → To
const toEmailsList = (extracted.lead_contacts || [])
  .map(c => c.email)
  .filter(Boolean);
const toEmails = toEmailsList.join(', ');

// Build CC: original sender (if partner/Drata) + yourcompany sales
const EXCLUDE_FROM_CC = ['yourcompany.com'];
const originalFrom = extracted.fromAddress || '';
const fromDomain = originalFrom.split('@')[1] || '';

const ccEmailsList = [];
// Include the introducer in CC if they're from a partner domain
if (originalFrom && !EXCLUDE_FROM_CC.some(d => fromDomain.endsWith(d))) {
  ccEmailsList.push(originalFrom);
}
// Always CC team@company.com
ccEmailsList.push('team@company.com');

// Signature HTML
const signature = '<br><br>Best,<br><br>' +
  '[YOUR-EMAIL-SIGNATURE-HTML]';

// Build Graph API reply body
const replyBody = {
  comment: htmlContent + signature,
  message: {
    from: {
      emailAddress: {
        address: 'person1@company.com',
        name: 'Your Name'
      }
    },
    toRecipients: toEmailsList.map(e => ({ emailAddress: { address: e } })),
    ccRecipients: ccEmailsList.map(e => ({ emailAddress: { address: e } }))
  }
};

return [{
  json: {
    htmlContent,
    toEmails,
    ccEmails: ccEmailsList.join(', '),
    subject: extracted.subject,
    messageId: emailRaw.id,
    replyBody
  }
}];

// Calculate expiration date: 2 days from now
const expirationDate = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000);
const expirationDateTime = expirationDate.toISOString();

return {
  json: {
    changeType: "created",
    notificationUrl: "https://[your-n8n-domain]/webhook/outlook-emails",
    resource: "users/team@company.com/mailFolders/Inbox/messages",
    expirationDateTime: expirationDateTime,
    clientState: "[your-webhook-secret]"
  }
};

// Extract subscriptions matching our notificationUrl
const items = $input.all();
const response = items[0].json;
const subs = response.value || [];

// Filter to only our webhook subscriptions
const toDelete = subs.filter(s => 
  s.notificationUrl && s.notificationUrl.includes('outlook-emails')
);

if (toDelete.length === 0) {
  // No subs to delete - return sentinel so DELETE node is skipped gracefully
  return [{ json: { id: '__none__', skip: true } }];
}

// Return one item per subscription ID
return toDelete.map(s => ({ json: { id: s.id, skip: false } }));

const item = $input.first().json;
const msgId = item.body?.value?.[0]?.resourceData?.id;

if (!msgId) return [{ json: item }]; // no message ID, let it through

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIds) staticData.processedIds = [];

// Clean up old IDs — keep only last 500 to prevent unbounded growth
if (staticData.processedIds.length > 500) {
  staticData.processedIds = staticData.processedIds.slice(-500);
}

if (staticData.processedIds.includes(msgId)) {
  // Already processed — return empty to stop execution
  return [];
}

// New message — record it and continue
staticData.processedIds.push(msgId);
return [{ json: item }];

